<script>
const paths={rewind:'<path d="M11 6 4 12l7 6V6Zm9 0-7 6 7 6V6Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',plus:'<path d="M12 5v14M5 12h14"/>',library:'<path d="M5 4h5v16H5zM14 4l5-1 3 16-5 1z"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z"/>',export:'<path d="M12 15V3m-4 4 4-4 4 4M5 12v8h14v-8"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3Z"/>',note:'<path d="M5 4h14v12l-5 4H5V4Zm9 16v-4h5M8 8h8M8 12h5"/>',clock:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>'};
const icon=name=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(paths[name]||paths.bookmark)+'</svg>';
document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
