function inline(s){return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')}
function markdown(text,title){const lines=text.replace(/\r/g,'').split('\n');let html='',code=[],inCode=false,lang='',list='',paragraph=[];
 const flush=()=>{if(paragraph.length){html+='<p>'+inline(paragraph.join('\n'))+'</p>';paragraph=[]}if(list){html+='</'+list+'>';list=''}};
 let first=true;for(const line of lines){if(/^\s*```/.test(line)){flush();if(inCode){html+='<div class="code"><div class="code-head"><span>'+esc(lang||'code')+'</span><span>● ● ●</span></div><pre><code>'+esc(code.join('\n'))+'</code></pre></div>';code=[];inCode=false}else{inCode=true;lang=line.trim().slice(3).trim()}continue}if(inCode){code.push(line);continue}if(first&&line.trim()){first=false;if(line.replace(/^#+\s*/,'').trim()===title.trim())continue}if(!line.trim()){flush();continue}const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){flush();const tag=heading[1].length<3?'h2':'h3';html+='<'+tag+'>'+inline(heading[2])+'</'+tag+'>';continue}if(/^[一二三四五六七八九十]+、/.test(line)){flush();html+='<h2>'+inline(line)+'</h2>';continue}const li=line.match(/^\s*(?:([-*•])|\d+[.)])\s+(.+)$/);if(li){if(paragraph.length){html+='<p>'+inline(paragraph.join('\n'))+'</p>';paragraph=[]}const next=li[1]?'ul':'ol';if(list!==next){if(list)html+='</'+list+'>';html+='<'+next+'>';list=next}html+='<li>'+inline(li[2])+'</li>';continue}if(line.startsWith('> ')){flush();html+='<blockquote>'+inline(line.slice(2))+'</blockquote>';continue}if(list){html+='</'+list+'>';list=''}paragraph.push(line)}flush();if(inCode)html+='<div class="code"><pre><code>'+esc(code.join('\n'))+'</code></pre></div>';return html}
function renderReader(c){const minutes=Math.max(1,Math.ceil(c.body.length/500));$('reader').innerHTML='<div class="entry-meta"><span class="source-badge">'+icon('bookmark')+esc(c.source)+'</span><span>·</span><span>'+esc(c.date)+'</span></div><h1>'+esc(c.title||'未命名收藏')+'</h1><div class="submeta">'+icon('clock')+'<span>约 '+minutes+' 分钟阅读</span><span>·</span><span>'+c.body.length+' 字</span>'+(c.hasImage?'<span>· 含原图</span>':'')+'</div>'+(c.note?'<aside class="note"><div class="note-label">'+icon('note')+'留给未来的自己</div><p>'+esc(c.note)+'</p></aside>':'<div style="height:24px"></div>')+(c.question?'<details class="question"><summary>这段回答，来自什么问题？</summary><p>'+esc(c.question)+'</p></details>':'')+(c.hasImage?'<div class="image-note"><span>原图已保留 · 识别文字可编辑核对</span><button class="tool" onclick="send(\'attachment\')">查看原图 ↗</button></div>':'')+'<article class="article">'+markdown(c.body,c.title)+'</article>'+(c.sourceURL?'<details class="question"><summary>原会话链接</summary><p>'+esc(c.sourceURL)+'</p></details>':'')+'<div class="article-end">REWIND</div>'}
window.updateState=function(s){state=s;$('count').textContent=s.query?s.clips.length+' / '+s.total:s.total;if(document.activeElement!==$('search'))$('search').value=s.query;const fragment=document.createDocumentFragment();s.clips.forEach(c=>{let el=document.createElement('button');el.className='card'+(c.id===s.selectedID?' selected':'');el.setAttribute('aria-label',c.title);el.setAttribute('aria-pressed',c.id===s.selectedID);el.innerHTML='<div class="card-meta"><span class="source-dot"></span><span>'+esc(c.source)+'</span><span class="date">'+esc(c.date.replace(/^\d{4}[\/年-]/,''))+'</span></div><div class="card-title">'+esc(c.title||'未命名收藏')+'</div><div class="card-excerpt">'+(c.hasImage?'▧ ':'')+esc((c.note||c.body).replace(/[\n#`]/g,' '))+'</div>';el.onclick=()=>{editing=false;send('select',{id:c.id})};fragment.appendChild(el)});$('cards').replaceChildren(fragment);if(!s.clips.length)$('cards').innerHTML='<div class="no-results">'+(s.query?'没有找到相关收藏<br>换个原文或备注里的关键词试试':'把值得留下的回答<br>放进你的收藏库')+'</div>';const c=s.clips.find(c=>c.id===s.selectedID);if(shownID!==s.selectedID){editing=false;shownID=s.selectedID;$('scroll').scrollTop=0;closeMenu()}$('reader').hidden=!c||editing;$('editor').hidden=!c||!editing;$('empty').hidden=!!c;$('toolbar-tools').hidden=!c;$('copy-tools').hidden=!c;$('mode-label').textContent=editing?'编辑':'阅读';$('feedback').textContent=s.feedback||'只在本机保存';if(c&&!editing){const version=JSON.stringify(c);if(version!==shownVersion){renderReader(c);shownVersion=version}}};
function startEditing(){let c=state.clips.find(c=>c.id===state.selectedID);if(!c)return;editing=true;$('edit-title').value=c.title;$('edit-note').value=c.note;$('edit-question').value=c.question;$('edit-url').value=c.sourceURL;$('edit-body').value=c.body;$('reader').hidden=true;$('editor').hidden=false;$('mode-label').textContent='编辑';$('scroll').scrollTop=0;$('edit-title').focus()}
