function syncEdit(){if(!editing)return;send('edit',{id:state.selectedID,title:$('edit-title').value,note:$('edit-note').value,question:$('edit-question').value,sourceURL:$('edit-url').value,body:$('edit-body').value})}
['edit-title','edit-note','edit-question','edit-url','edit-body'].forEach(id=>$(id).addEventListener('input',syncEdit));
$('search').addEventListener('input',()=>{editing=false;send('search',{query:$('search').value})});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();if(editing)send('done');else{$('search').value='';send('search',{query:''})}}});
document.addEventListener('click',e=>{if(!e.target.closest('.menu-wrap'))closeMenu()});
